export function alpha(x) {
  return 'ALPHA:' + String(x);
}

// Heavy implementation never surfaced by the barrel (index.js re-exports
// only alpha) and never imported by anyone. Statically unreachable through
// the re-export chain — the intended stub target.
export function beta(input) {
  const tokens = String(input).split(/\s+/).filter(Boolean);
  const counts = new Map();
  for (const t of tokens) {
    const key = t.toLowerCase().replace(/[^a-z0-9]/g, '');
    if (!key) continue;
    counts.set(key, (counts.get(key) ?? 0) + 1);
  }
  const ranked = [...counts.entries()].sort((a, b) => {
    if (b[1] !== a[1]) return b[1] - a[1];
    return a[0] < b[0] ? -1 : 1;
  });
  const summary = ranked
    .slice(0, 10)
    .map(([word, n]) => `${word}=${n}`)
    .join(',');
  return { total: tokens.length, distinct: counts.size, summary };
}
